insert into public.subjects (id, name, grade, sort_order) values ('chemistry', 'Chemistry', 'Grade 11', 1) on conflict (id) do update set name = excluded.name, grade = excluded.grade, sort_order = excluded.sort_order;
insert into public.subject_chapters (id, subject_id, unit, title, source, intro, exam_date, sort_order) values ('chem-g11-u1-bohr', 'chemistry', 'Unit 1 · Part II', 'The Bohr model and wave–particle duality', 'Teacher slides (Tamiru), Part II — sections 1.5.4 to 1.5.6', 'One question runs through this whole chapter: **why does an atom only give out certain colors of light?** Bohr answered it with one bold idea — an electron can only have certain energies — and that idea explains the radius formula, the energy formula, and the hydrogen spectrum. Then de Broglie explained *why* the energies are fixed: electrons behave like waves. Understand the staircase picture in section 1 and everything else follows.', '2026-10-13', 1) on conflict (id) do update set subject_id = excluded.subject_id, unit = excluded.unit, title = excluded.title, source = excluded.source, intro = excluded.intro, exam_date = excluded.exam_date, sort_order = excluded.sort_order;
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('bohr-1-problem', 'chem-g11-u1-bohr', 1, 'The problem Bohr solved', '1.5.4', 'Energy inside an atom comes in fixed steps — like a staircase, not a ramp.', '[{"kind":"p","text":"Rutherford’s model had the electron circling the nucleus like a planet. But physics said a circling charge should **constantly lose energy as light**, spiral inward and crash into the nucleus in a fraction of a second. Atoms obviously don’t collapse — so the model was missing something."},{"kind":"p","text":"There was a second clue. When hydrogen gas is heated, it doesn’t glow with every color. It gives out only a few **sharp lines** of specific colors (its *line spectrum*). If the electron could have any energy, we would see every color."},{"kind":"callout","tone":"idea","title":"Bohr’s answer (1913)","text":"The electron can only have **certain energies**. It can stand on step 1, step 2, step 3… but never between steps. This is what **quantized** means. Light comes out only when the electron jumps down a step, so only certain amounts of energy — certain colors — ever appear."},{"kind":"table","head":["Staircase picture","In the atom"],"rows":[["Standing on a step","Electron in an allowed orbit — no energy gained or lost"],["Climbing up","Electron absorbs exactly the right energy of light"],["Stepping down","Electron gives out light (a photon)"],["Can’t stand between steps","Energy is quantized"]]}]'::jsonb, '[{"q":"Why didn’t Rutherford’s atom work?","a":"A circling electron should keep losing energy as light and spiral into the nucleus. Real atoms are stable, so something was wrong."},{"q":"What does it mean that energy in an atom is *quantized*?","a":"The electron can only have certain specific energies, not any value in between — like standing only on the steps of a staircase."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=au2HCVn9IJI","title":"Bohr Model of the Hydrogen Atom","channel":"Professor Dave Explains","minutes":5}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('bohr-2-assumptions', 'chem-g11-u1-bohr', 2, 'Bohr’s assumptions — and why each one is there', '1.5.4', 'Each assumption is a rule invented to make the atom stable and explain the line spectrum.', '[{"kind":"steps","items":["**Circular orbits.** The electron moves around the nucleus in a circle. *(Simplest picture to start from.)*","**Farther = more energy.** The farther the orbit from the nucleus, the higher the electron’s energy. *(Like height on the staircase.)*","**Only some orbits are allowed** — the orbits are quantized. *(This is the big new idea.)*","**Angular momentum is quantized:** mvr = n·h/2π, where n = 1, 2, 3… *(This is the mathematical rule that picks out which orbits are allowed.)*","**No energy loss inside an orbit.** While the electron stays in one orbit it neither gains nor loses energy. *(This fixes the ‘atom collapses’ problem by declaring it can’t happen.)*","**Jumps need exact light.** Moving up needs absorbed light; falling down gives out light. The photon’s energy **exactly equals** the difference between the two levels. *(This explains the sharp spectral lines.)*"]},{"kind":"callout","tone":"book","title":"About assumption 2 on the slide","text":"The slide says energy is *proportional* to distance. Take that as ‘more distance, more energy’. The real relationship is not a straight proportion: radius grows like n² while energy goes like −1/n² (sections 3 and 4)."}]'::jsonb, '[{"q":"Which assumption explains why hydrogen gives sharp lines instead of a rainbow?","a":"Number 6: a photon’s energy exactly equals the gap between two allowed levels, and there are only a few gaps — so only a few colors."},{"q":"Which assumption ‘solves’ the collapse problem?","a":"Number 5: in an allowed orbit the electron does not lose energy, so it does not spiral inward."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('bohr-3-radius', 'chem-g11-u1-bohr', 3, 'How big is each orbit? r = n² × 0.53 Å', '1.5.4', 'Two ideas combined — force balance plus the quantum rule — give one simple result: orbit size grows with n².', '[{"kind":"p","text":"Bohr combined two conditions. You don’t need to reproduce every algebra step, but you should know **where each piece comes from**:"},{"kind":"bullets","items":["**Balance of forces** (a stable circle): the pull of the nucleus equals the force needed to keep moving in a circle → e²/r² = mv²/r.","**The quantum rule:** mvr = nh/2π → solve for v = nh / (2πmr).","Put that v into the first equation and solve for r. Everything except n is a constant."]},{"kind":"formula","text":"r = n² · h² / (4π²me²) = n² × a₀","note":"a₀ = 0.53 Å, the Bohr radius"},{"kind":"table","head":["n","Radius","Compared with n = 1"],"rows":[["1","0.53 Å","1×"],["2","2.12 Å","4×"],["3","4.76 Å","9×"]]},{"kind":"callout","tone":"idea","text":"**n²** is the pattern to remember: double n and the orbit gets **four** times bigger, not two. (1 Å = 10⁻¹⁰ m.)"}]'::jsonb, '[{"q":"What is the radius of the n = 4 orbit in hydrogen?","a":"r = 4² × 0.53 Å = 16 × 0.53 = 8.48 Å."},{"q":"Which two conditions did Bohr combine to get the radius formula?","a":"The balance of forces for a stable circular orbit, and the quantum condition mvr = nh/2π."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=7Zin8hG9Nhw","title":"Bohr model energy levels (derivation using physics)","channel":"Khan Academy","minutes":12}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('bohr-4-energy', 'chem-g11-u1-bohr', 4, 'Energy levels: why the energy is negative', '1.5.4', 'Eₙ = −2.18 × 10⁻¹⁸ J / n². The minus sign means ‘trapped’: you must add energy to free the electron.', '[{"kind":"formula","text":"Eₙ = −R_H / n² = −2.18 × 10⁻¹⁸ J / n²","note":"R_H = 2.18 × 10⁻¹⁸ J (Rydberg constant, energy form)"},{"kind":"p","text":"Zero energy is defined as an electron that is **completely free**, far away from the nucleus (n = ∞). A trapped electron has *less* energy than a free one, so its energy is **below zero — negative**."},{"kind":"table","head":["Level","Energy (J)","Name"],"rows":[["n = 1","−2.18 × 10⁻¹⁸","Ground state — lowest, most stable"],["n = 2","−5.45 × 10⁻¹⁹","Excited state"],["n = 3","−2.42 × 10⁻¹⁹","Excited state"],["n = ∞","0","Electron removed (ion formed)"]]},{"kind":"callout","tone":"warn","title":"The confusing part","text":"Closer to the nucleus (smaller n) the energy is **more negative**, which means **lower** and **more stable**. ‘Bigger number’ after the minus sign = deeper in the well. Going up from n = 1 to n = 2, the energy *rises* from −2.18 to −0.545 (× 10⁻¹⁸ J)."},{"kind":"p","text":"Useful consequence: removing the electron from the ground state needs exactly **2.18 × 10⁻¹⁸ J** per atom — hydrogen’s ionization energy (1312 kJ/mol)."}]'::jsonb, '[{"q":"Is an electron at n = 1 higher or lower in energy than at n = 3?","a":"Lower. −2.18 × 10⁻¹⁸ J is more negative than −2.42 × 10⁻¹⁹ J, so n = 1 is the lowest, most stable level."},{"q":"What does E = 0 represent in the Bohr model?","a":"An electron that is completely free from the nucleus (n = ∞)."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=nJ-PtF14EFw","title":"Bohr model energy levels","channel":"Khan Academy","minutes":10}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('bohr-5-spectra', 'chem-g11-u1-bohr', 5, 'Jumps between levels make the line spectrum', '1.5.4', 'Every spectral line is one specific jump. Bigger drop → more energy → shorter wavelength.', '[{"kind":"formula","text":"ΔE = E_final − E_initial = −2.18 × 10⁻¹⁸ J (1/n_f² − 1/n_i²)"},{"kind":"bullets","items":["**ΔE positive → absorbed** (electron goes up, n_f > n_i).","**ΔE negative → emitted** (electron falls, n_f < n_i). The light carries away |ΔE|.","Link energy to light with **E = hν = hc/λ** (h = 6.626 × 10⁻³⁴ J·s, c = 3.00 × 10⁸ m/s)."]},{"kind":"example","title":"Worked example — the red line of hydrogen (n = 3 → n = 2)","steps":["ΔE = −2.18 × 10⁻¹⁸ (1/2² − 1/3²) = −2.18 × 10⁻¹⁸ × 0.1389 = −3.03 × 10⁻¹⁹ J (negative: emitted).","Energy of the photon = 3.03 × 10⁻¹⁹ J.","λ = hc / E = (6.626 × 10⁻³⁴ × 3.00 × 10⁸) / 3.03 × 10⁻¹⁹ = 6.56 × 10⁻⁷ m."],"answer":"λ = 656 nm — the red line in the hydrogen spectrum."},{"kind":"table","head":["Series","Electron falls to","From","Region"],"rows":[["Lyman","n = 1","2, 3, 4…","Ultraviolet"],["Balmer","n = 2","3, 4, 5…","Visible (and near UV)"],["Paschen","n = 3","4, 5, 6…","Infrared"],["Brackett","n = 4","5, 6, 7…","Infrared"]]},{"kind":"callout","tone":"idea","title":"Remember the series by where the electron lands","text":"Lyman lands on 1, Balmer on 2, Paschen on 3, Brackett on 4. Landing on n = 1 is the biggest drop, so Lyman lines have the most energy — ultraviolet."},{"kind":"p","text":"Wavelength-form of the same idea (the Rydberg equation): **1/λ = R (1/n_low² − 1/n_high²)**, with R = 1.097 × 10⁷ m⁻¹."}]'::jsonb, '[{"q":"An electron falls from n = 4 to n = 2. Absorbed or emitted? Which series?","a":"Emitted (it falls). It lands on n = 2, so it is a Balmer line — visible light."},{"q":"Which emits light of shorter wavelength: 3 → 1 or 3 → 2?","a":"3 → 1. It is a bigger energy drop, and more energy means shorter wavelength."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=mXxsT1ut35Q","title":"Bohr Model, Electron Transitions, Atomic Energy Levels (calculations)","channel":"The Organic Chemistry Tutor","minutes":22}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('bohr-6-limitations', 'chem-g11-u1-bohr', 6, 'Where the Bohr model fails', '1.5.5', 'Bohr works only for one-electron atoms, and his exact orbits break Heisenberg’s principle.', '[{"kind":"steps","items":["**Only one-electron atoms.** It works for H, He⁺ and Li²⁺, but cannot explain the spectra of atoms with more electrons, because it ignores electron–electron repulsion.","**Cannot explain the Zeeman effect** — spectral lines splitting into several lines in a magnetic field (or in an electric field: the Stark effect).","**Breaks the uncertainty principle.** A fixed orbit means knowing the electron’s exact position *and* speed at once, which Heisenberg showed is impossible (Part III)."]},{"kind":"p","text":"Also: Bohr *assumed* the fixed energy levels without a physical reason for them. de Broglie supplied the reason next."}]'::jsonb, '[{"q":"Name the three limitations of the Bohr model.","a":"Only works for one-electron atoms; can’t explain the Zeeman (and Stark) effect; violates Heisenberg’s uncertainty principle."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('bohr-7-de-broglie', 'chem-g11-u1-bohr', 7, 'Wave–particle duality: λ = h / mv', '1.5.6', 'Everything moving has a wavelength, but only for tiny things like electrons is it big enough to matter.', '[{"kind":"p","text":"Light was known to act like particles (photons). In 1924 **de Broglie** flipped the idea: maybe **particles act like waves**. An electron trapped around a nucleus would then behave like a vibrating guitar string — only certain waves fit, which is exactly why only certain energies are allowed."},{"kind":"formula","text":"λ = h / (m·v)","note":"m in kg, v in m/s, h = 6.626 × 10⁻³⁴ J·s → λ in metres"},{"kind":"p","text":"The slide derives this by setting E = mc² equal to E = hc/λ and replacing c with v. Treat that as a memory aid for where the formula comes from."},{"kind":"table","head":["Object","Mass and speed","Wavelength"],"rows":[["Electron","9.11 × 10⁻³¹ kg at 2.2 × 10⁶ m/s","≈ 0.33 nm — about the size of an atom, so wave behavior matters"],["Baseball","0.145 kg at 40 m/s","≈ 1.1 × 10⁻³⁴ m — far too small to ever notice"]]},{"kind":"callout","tone":"idea","text":"Because m is on the bottom, **heavier or faster → shorter wavelength**. That’s why wave behavior only shows up at the atomic scale: this dual nature is called **wave–particle duality**."}]'::jsonb, '[{"q":"A proton and an electron move at the same speed. Which has the longer de Broglie wavelength?","a":"The electron. It has much less mass, and λ = h/mv, so smaller m gives larger λ."},{"q":"How did de Broglie’s idea explain Bohr’s fixed energy levels?","a":"If the electron is a wave, only waves that fit around the orbit are allowed, so only certain orbits and energies exist."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=cYyFPFU6s_A","title":"De Broglie Wavelength Problems In Chemistry","channel":"The Organic Chemistry Tutor","minutes":11}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('bohr-8-practice', 'chem-g11-u1-bohr', 8, 'Your slide’s practice questions — worked', 'Content-checking questions', 'Three formulas cover all six: c = λν, E = hν = hc/λ, and λ = h/mv.', '[{"kind":"callout","tone":"warn","title":"Try first","text":"Cover each solution and attempt the question yourself before reading it. Constants: h = 6.626 × 10⁻³⁴ J·s · c = 3.00 × 10⁸ m/s · Nₐ = 6.022 × 10²³ · electron mass 9.109 × 10⁻³¹ kg."},{"kind":"example","title":"1. Radio station at 992 kHz — wavelength?","steps":["Convert: 992 kHz = 9.92 × 10⁵ s⁻¹.","λ = c/ν = 3.00 × 10⁸ / 9.92 × 10⁵."],"answer":"λ ≈ 302 m"},{"kind":"example","title":"2. Energy per photon at ν = 3.73 × 10¹⁴ s⁻¹","steps":["E = hν = 6.626 × 10⁻³⁴ × 3.73 × 10¹⁴."],"answer":"E ≈ 2.47 × 10⁻¹⁹ J per photon"},{"kind":"example","title":"3. Microwave at λ = 1.20 cm — per photon and per mole","steps":["Convert: 1.20 cm = 0.0120 m.","(a) E = hc/λ = (6.626 × 10⁻³⁴ × 3.00 × 10⁸) / 0.0120 = 1.66 × 10⁻²³ J per photon.","(b) Multiply by Avogadro’s number: 1.66 × 10⁻²³ × 6.022 × 10²³ = 9.97 J/mol, then divide by 1000."],"answer":"(a) 1.66 × 10⁻²³ J/photon · (b) 9.97 × 10⁻³ kJ/mol"},{"kind":"example","title":"4. Frequency emitted when hydrogen’s electron falls (a) 3 → 2 (b) 4 → 1","steps":["|ΔE| = 2.18 × 10⁻¹⁸ (1/n_f² − 1/n_i²), then ν = |ΔE| / h.","(a) 2.18 × 10⁻¹⁸ (1/4 − 1/9) = 3.03 × 10⁻¹⁹ J → ν = 3.03 × 10⁻¹⁹ / 6.626 × 10⁻³⁴.","(b) 2.18 × 10⁻¹⁸ (1/1 − 1/16) = 2.04 × 10⁻¹⁸ J → ν = 2.04 × 10⁻¹⁸ / 6.626 × 10⁻³⁴."],"answer":"(a) 4.57 × 10¹⁴ s⁻¹ · (b) 3.08 × 10¹⁵ s⁻¹"},{"kind":"example","title":"5. Electrons with λ = 84.4 nm — what speed?","steps":["Rearrange λ = h/mv to v = h/(mλ).","v = 6.626 × 10⁻³⁴ / (9.109 × 10⁻³¹ × 84.4 × 10⁻⁹)."],"answer":"v ≈ 8.62 × 10³ m/s"},{"kind":"example","title":"6. Proton (1.67 × 10⁻²⁷ kg) at 2.55 × 10⁶ m/s — wavelength in nm?","steps":["λ = h/mv = 6.626 × 10⁻³⁴ / (1.67 × 10⁻²⁷ × 2.55 × 10⁶) = 1.56 × 10⁻¹³ m.","1 m = 10⁹ nm."],"answer":"λ ≈ 1.56 × 10⁻⁴ nm"},{"kind":"callout","tone":"book","text":"Your slide numbers two questions as ‘5’. The second one is question 6 here."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.subject_chapters (id, subject_id, unit, title, source, intro, exam_date, sort_order) values ('chem-g11-u1-quantum', 'chemistry', 'Unit 1 · Part III', 'Quantum model, electron configurations and periodic trends', 'Teacher slides (Tamiru), Part III — sections 1.6 to 1.8.3', 'This chapter replaces Bohr’s neat orbits with **clouds of probability**, then gives every electron an *address* (four quantum numbers), fills atoms up electron by electron, and finally shows that the periodic table is simply a map of those addresses. One idea — **effective nuclear charge** — then explains the trends. If you understand the address idea (section 3) and Z_eff (section 8), most exam questions become reasoning instead of memory.', '2026-10-13', 2) on conflict (id) do update set subject_id = excluded.subject_id, unit = excluded.unit, title = excluded.title, source = excluded.source, intro = excluded.intro, exam_date = excluded.exam_date, sort_order = excluded.sort_order;
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-1-heisenberg', 'chem-g11-u1-quantum', 1, 'Heisenberg: you can’t pin an electron down', '1.6.1', 'Measuring an electron’s position disturbs its momentum, so we can never know both exactly.', '[{"kind":"formula","text":"Δx · Δp ≥ h / 4π","note":"Δx = uncertainty in position, Δp = uncertainty in momentum (p = mv)"},{"kind":"p","text":"To *see* an electron you must hit it with light. To locate it precisely you need short-wavelength, high-energy light — which knocks the electron and changes its speed. Gentler, long-wavelength light leaves the speed alone but blurs the position. **Better position ↔ worse momentum.** This is a law of nature, not a weakness of our instruments."},{"kind":"callout","tone":"idea","title":"Why it matters","text":"Bohr’s orbit claims an exact path — exact position and exact speed at every moment. Heisenberg says that’s impossible, so we stop describing paths and start describing **probabilities**: where the electron is *likely* to be."},{"kind":"callout","tone":"book","title":"Slide error","text":"The slide says **1827**. Heisenberg proposed the principle in **1927**. (In 1827 he hadn’t been born.)"}]'::jsonb, '[{"q":"State Heisenberg’s uncertainty principle in one sentence.","a":"It is impossible to know both the exact position and the exact momentum of an electron at the same time."},{"q":"Why does the uncertainty principle undermine Bohr’s model?","a":"Bohr’s fixed orbits assume we know the electron’s exact position and speed together, which the principle forbids."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=TQKELOE9eY4","title":"What is the Heisenberg Uncertainty Principle?","channel":"TED-Ed","minutes":5}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-2-orbitals', 'chem-g11-u1-quantum', 2, 'Schrödinger, ψ, and the orbital', '1.6', 'An orbital is not a path — it is the region where the electron is found about 90% of the time.', '[{"kind":"bullets","items":["**Schrödinger (1926)** described the electron as a wave with an equation. Its solution is the **wave function ψ** (psi).","**ψ² = probability density** — how likely the electron is to be found at each point.","Plotting many likely positions gives a fuzzy **electron cloud**, dense where the electron is often found.","An **orbital** is the region that contains about **90%** of that probability. Its outline is drawn as a *boundary surface*."]},{"kind":"table","head":["Bohr ‘orbit’","Quantum ‘orbital’"],"rows":[["Exact circular path","Region of probability"],["Position known exactly","Only the likely location is known"],["Flat circle","3-D shape (sphere, dumbbell, …)"]]},{"kind":"callout","tone":"book","text":"The equation printed on the slide is garbled and you will not be asked to reproduce it. Know the ideas: ψ is the wave function, ψ² gives probability, and solving it gives the quantum numbers. Schrödinger published in **1926** (the slide says 1927)."}]'::jsonb, '[{"q":"What is the difference between an orbit and an orbital?","a":"An orbit is Bohr’s exact circular path. An orbital is a 3-D region where the electron is likely to be found (about 90% probability)."},{"q":"What does ψ² tell us?","a":"The probability of finding the electron at a given point in space."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-3-quantum-numbers', 'chem-g11-u1-quantum', 3, 'The four quantum numbers: an electron’s address', '1.6.2', 'n = which floor · l = which kind of room · mₗ = which room · mₛ = which of the two occupants.', '[{"kind":"table","head":["Number","Tells you","Allowed values"],"rows":[["n — principal","Shell: size and energy (the floor)","1, 2, 3, …"],["l — angular momentum","Subshell: shape (the kind of room: s, p, d, f)","0 to n − 1"],["mₗ — magnetic","Orbital: orientation (which room)","−l to +l"],["mₛ — spin","Spin direction (which of the two occupants)","+½ or −½"]]},{"kind":"table","head":["l value","0","1","2","3"],"rows":[["Letter","s","p","d","f"],["Orbitals (2l + 1)","1","3","5","7"],["Max electrons","2","6","10","14"]]},{"kind":"callout","tone":"idea","title":"The rules chain together","text":"**n limits l, and l limits mₗ.** Pick n; then l can be 0 up to n − 1; then mₗ runs from −l to +l. Each orbital holds 2 electrons (spin up and spin down). So a shell holds **n² orbitals** and **2n² electrons**."},{"kind":"example","title":"Worked example — all orbitals with n = 2","steps":["l can be 0 or 1 (from 0 to n − 1).","l = 0 → 2s → mₗ = 0 → 1 orbital.","l = 1 → 2p → mₗ = −1, 0, +1 → 3 orbitals.","Total 4 orbitals (= 2²), each with mₛ = +½ or −½ → 8 electrons (= 2 × 2²)."],"answer":"n = 2 has 4 orbitals and holds 8 electrons."},{"kind":"example","title":"Spotting an impossible set","steps":["(n, l, mₗ, mₛ) = (2, 2, 0, +½): l must be less than n, and 2 is not less than 2 → impossible.","(3, 1, −2, −½): mₗ can only be −1, 0, +1 when l = 1 → impossible.","(3, 2, −1, +½): l = 2 < 3, mₗ = −1 is within −2…+2, mₛ is ±½ → allowed (a 3d electron)."],"answer":"Check l < n first, then |mₗ| ≤ l, then mₛ = ±½."}]'::jsonb, '[{"q":"How many orbitals and electrons fit in the n = 3 shell?","a":"n² = 9 orbitals (one 3s, three 3p, five 3d) and 2n² = 18 electrons."},{"q":"Is (1, 1, 0, +½) a possible set of quantum numbers?","a":"No. When n = 1, l can only be 0."},{"q":"What does each quantum number describe?","a":"n — shell (size and energy); l — subshell shape; mₗ — orbital orientation; mₛ — electron spin."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=Aoi4j8es4gQ","title":"Quantum Numbers, Atomic Orbitals, and Electron Configurations","channel":"Professor Dave Explains","minutes":9},{"url":"https://www.youtube.com/watch?v=eRIN9CPDrpo","title":"Quantum Numbers","channel":"The Organic Chemistry Tutor","minutes":12}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-4-shapes', 'chem-g11-u1-quantum', 4, 'Shapes of s, p and d orbitals', '1.6.3', 's is a sphere, p is a dumbbell along an axis, d is mostly a four-leaf clover — and the number of orientations is 2l + 1.', '[{"kind":"table","head":["Type","Shape","How many","First appears"],"rows":[["s (l = 0)","Sphere around the nucleus","1","n = 1"],["p (l = 1)","Dumbbell: two lobes, nucleus between","3 — p_x, p_y, p_z","n = 2"],["d (l = 2)","Four-leaf clover (d_{z²} is a dumbbell with a ring)","5","n = 3"],["f (l = 3)","Complex","7","n = 4"]]},{"kind":"bullets","items":["**s orbitals get bigger as n increases**: 1s < 2s < 3s, but all are spheres.","The three p orbitals point along the **x, y and z axes**, at right angles to each other. They have the **same energy** — they are *degenerate*.","Each p orbital has a **nodal plane** through the nucleus where the electron is never found (for p_x it is the yz plane).","The five d orbitals: d_{xy}, d_{yz}, d_{xz}, d_{x²−y²} and d_{z²}."]}]'::jsonb, '[{"q":"Why is there no 1p or 2d orbital?","a":"l must be less than n. For n = 1, l = 0 only (s); for n = 2, l = 0 or 1 (s and p), so d (l = 2) first appears at n = 3."},{"q":"What does ‘degenerate’ mean for the three 2p orbitals?","a":"They have the same energy; they differ only in direction."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=K-jNgq16jEY","title":"Electron Orbitals - s, p & d","channel":"Anna Tanczos","minutes":2}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-5-configuration', 'chem-g11-u1-quantum', 5, 'Writing electron configurations: three rules', '1.7', 'Fill the lowest energy first (Aufbau), at most two per orbital with opposite spins (Pauli), and spread out before pairing (Hund).', '[{"kind":"p","text":"Notation: **nlᵉ** — shell number, subshell letter, number of electrons as a superscript. Example: 1s² 2s² 2p³ is nitrogen (7 electrons)."},{"kind":"steps","items":["**Aufbau principle** — fill from lowest energy upward: 1s 2s 2p 3s 3p **4s 3d** 4p 5s 4d 5p 6s 4f 5d 6p… Note 4s fills *before* 3d.","**Pauli exclusion principle** — an orbital holds at most **2 electrons**, with **opposite spins** (↑↓). No two electrons in an atom share all four quantum numbers.","**Hund’s rule** — in orbitals of equal energy (like the three 2p), put **one electron in each first**, all with the same spin, before pairing. Electrons repel, so they spread out."]},{"kind":"callout","tone":"idea","title":"Shortcut for the filling order","text":"Fill in order of increasing **n + l**; if two tie, the one with smaller n goes first. 4s: 4 + 0 = 4; 3d: 3 + 2 = 5 → 4s first."},{"kind":"table","head":["Element","Z","Configuration","Orbital diagram (2p)"],"rows":[["C","6","1s² 2s² 2p²","↑ ↑ _"],["N","7","1s² 2s² 2p³","↑ ↑ ↑"],["O","8","1s² 2s² 2p⁴","↑↓ ↑ ↑"],["Ne","10","1s² 2s² 2p⁶","↑↓ ↑↓ ↑↓"]]},{"kind":"p","text":"**Noble-gas shorthand:** write the previous noble gas in brackets, then the rest. Iron (Z = 26) = [Ar] 4s² 3d⁶, where [Ar] = 1s² 2s² 2p⁶ 3s² 3p⁶."}]'::jsonb, '[{"q":"Write the configuration of sulfur (Z = 16).","a":"1s² 2s² 2p⁶ 3s² 3p⁴, or [Ne] 3s² 3p⁴."},{"q":"Why does nitrogen have three unpaired 2p electrons instead of one pair and one single?","a":"Hund’s rule: electrons occupy equal-energy orbitals singly first, because they repel each other."},{"q":"Why does 4s fill before 3d?","a":"4s has the lower energy (n + l = 4 versus 5 for 3d)."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=C6afrc1QS6Y","title":"Aufbau’s Principle, Hund’s Rule & Pauli’s Exclusion Principle","channel":"The Organic Chemistry Tutor","minutes":5}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-6-exceptions', 'chem-g11-u1-quantum', 6, 'The exceptions: chromium and copper', '1.7', 'A half-full (d⁵) or completely full (d¹⁰) d subshell is extra stable, so one 4s electron moves into 3d.', '[{"kind":"table","head":["","Expected","Actual","Why"],"rows":[["Cr (24)","[Ar] 4s² 3d⁴","[Ar] 4s¹ 3d⁵","Half-full 3d⁵ is more stable"],["Cu (29)","[Ar] 4s² 3d⁹","[Ar] 4s¹ 3d¹⁰","Full 3d¹⁰ is more stable"]]},{"kind":"p","text":"Why is this even possible? 4s and 3d are **very close in energy**, so moving one electron costs almost nothing — and a half-full or full set of d orbitals lowers the atom’s total energy (less repulsion, more symmetry). The atom simply picks the lowest-energy arrangement."},{"kind":"p","text":"The same thing happens lower in the table, where the energy gaps are even smaller: Mo [Kr] 5s¹ 4d⁵ · Ag [Kr] 5s¹ 4d¹⁰ · Pd [Kr] 4d¹⁰ · Au [Xe] 4f¹⁴ 5d¹⁰ 6s¹."}]'::jsonb, '[{"q":"Write the actual configuration of copper and explain it.","a":"[Ar] 4s¹ 3d¹⁰. A completely filled 3d subshell is more stable, and 4s and 3d are close enough in energy for one electron to move."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=Ur2PuzJ7KWs","title":"Electron Configuration Exceptions - Chromium & Copper","channel":"The Organic Chemistry Tutor","minutes":6}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-7-periodic-table', 'chem-g11-u1-quantum', 7, 'The periodic table is a map of configurations', '1.8.1 – 1.8.2', 'Period = outermost shell (n). Group = number of valence electrons. Block = the subshell being filled.', '[{"kind":"p","text":"**Periodic law:** properties repeat periodically when elements are arranged by increasing **atomic number** (Mendeleev arranged by atomic *mass*; that is the key difference from today’s table). 7 periods, 18 groups."},{"kind":"table","head":["Block","Filling","Where","Type"],"rows":[["s","s orbital","Groups 1–2 (+ He)","Main group"],["p","p orbitals","Groups 13–18","Main group"],["d","d orbitals","Groups 3–12","Transition"],["f","f orbitals","Lanthanides, actinides","Inner transition"]]},{"kind":"p","text":"Main-group elements are also called **representative** elements."},{"kind":"callout","tone":"idea","title":"Why same group = similar chemistry","text":"Chemistry is done by the **outer (valence) electrons**. Elements in a group have the same valence arrangement (all of group 1 end in s¹), so they react alike."},{"kind":"example","title":"Revision question 4 — 1s² 2s² 2p⁶ 3s² 3p⁵, without the table","steps":["Highest shell is n = 3 → **period 3**.","Valence electrons: 3s² 3p⁵ = **7** → p-block, **group 17**.","One electron short of a full shell → strongly **nonmetallic**, tends to **gain 1 electron**."],"answer":"Period 3, group 17, 7 valence electrons, nonmetal, gains one electron — it is chlorine."}]'::jsonb, '[{"q":"How is today’s periodic table different from Mendeleev’s?","a":"Today’s is ordered by atomic number; Mendeleev ordered by atomic mass."},{"q":"Two elements are in the same group but different periods. Similar properties?","a":"Similar, not identical. They share the same valence configuration, but the lower one has more shells, so its size and reactivity differ."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-8-zeff', 'chem-g11-u1-quantum', 8, 'Effective nuclear charge: the key to every trend', '1.8.3', 'Z_eff = Z − S: the real pull an outer electron feels after the inner electrons shield it.', '[{"kind":"formula","text":"Z_eff = Z − S","note":"Z = protons, S = shielding by electrons between the nucleus and the electron"},{"kind":"p","text":"Inner electrons sit between the nucleus and the outer electrons and cancel part of the nucleus’s pull. Sodium: Z = 11, its 10 inner electrons shield, so the outer 3s electron feels about **11 − 10 = +1**."},{"kind":"table","head":["","Across a period →","Down a group ↓"],"rows":[["What changes","One more proton each step, same shell","One more shell each step"],["Z_eff","Increases (shielding barely changes)","Roughly the same"],["Distance of outer electrons","About the same","Increases"]]},{"kind":"callout","tone":"idea","text":"Every trend in section 9 comes from these two facts: **across a period, pull (Z_eff) increases; down a group, distance increases.**"}]'::jsonb, '[{"q":"What is the approximate Z_eff felt by the 3s electron of magnesium (Z = 12)?","a":"12 − 10 = +2."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=MVEgoVJFg7E","title":"Nuclear Charge, Shielding Effect & Effective Nuclear Charge","channel":"Gradefruit","minutes":2}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-9-trends', 'chem-g11-u1-quantum', 9, 'Atomic radius and ionization energy', '1.8.3', 'Across a period: atoms shrink and hold electrons tighter. Down a group: atoms grow and hold electrons looser.', '[{"kind":"heading","text":"Atomic radius"},{"kind":"bullets","items":["Defined as **half the distance between two bonded nuclei** (r = d/2) — an isolated atom has no sharp edge.","**Decreases across a period**: Z_eff grows, pulling the same shell in tighter.","**Increases down a group**: each step adds a whole new shell.","**Cations are smaller** than their atom (lost electrons, often a whole shell): Na⁺ < Na.","**Anions are larger** than their atom (extra electron, more repulsion): Cl⁻ > Cl.","**Transition metals stay nearly the same size** across a period: the new electrons go into an *inner* d subshell, shielding the outer 4s electrons and cancelling the extra protons."]},{"kind":"example","title":"Exercise 1.12 Q3 — why is Na → Mg a big drop (186 → 160 pm) but Cr → Mn tiny (125 → 124 pm)?","steps":["Na → Mg: the extra electron goes into the **same outer shell** (3s), which shields poorly, so Z_eff jumps and the atom shrinks a lot.","Cr → Mn: the extra electron goes into the **inner 3d** subshell. It shields the outer 4s electrons and cancels the extra proton, so Z_eff barely changes."],"answer":"Main-group: the electron added to the outer shell shields poorly. Transition: the electron added to the inner d shields well."},{"kind":"example","title":"Exercise 1.12 Q2 — decreasing atomic size","steps":["(a) Sr > Ca > Mg — same group, more shells going down.","(b) K > Ca > Ga — same period (4), shrinking left to right.","(c) Rb > Br > Kr — Rb is in period 5; Br and Kr in period 4, Kr further right.","(d) Rb > Sr > Ca — Rb and Sr in period 5 (Rb further left); Ca is a period higher."],"answer":"Down a group → bigger. Across a period → smaller."},{"kind":"heading","text":"Ionization energy (IE)"},{"kind":"p","text":"The energy needed to **remove the outermost electron** from a gaseous atom: X(g) → X⁺(g) + e⁻. It is the opposite of atomic size:"},{"kind":"bullets","items":["**Increases across a period** — stronger pull (higher Z_eff), smaller atom.","**Decreases down a group** — the outer electron is farther away and better shielded.","**Each further electron is harder to remove** (IE₁ < IE₂ < IE₃…): the ion left behind is more positive. There is a huge jump when you start removing from a full inner shell."]},{"kind":"callout","tone":"warn","title":"Usually asked as reasoning","text":"Don’t memorize a list of rankings. Ask two questions: *how far is the outer electron* (shells), and *how strongly is it pulled* (Z_eff). Size and IE always move in opposite directions."}]'::jsonb, '[{"q":"Which is larger: Mg or Mg²⁺? Why?","a":"Mg. Mg²⁺ has lost both 3s electrons — its whole outer shell — and the remaining electrons are pulled in by the same nucleus."},{"q":"Which has the higher first ionization energy, Na or Cl?","a":"Cl. It is in the same period but further right, so it has a higher Z_eff and a smaller radius."},{"q":"Why do atomic radii decrease across a period even though electrons are added?","a":"The electrons go into the same shell while protons are added, so Z_eff increases and the cloud is pulled closer."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=hePb00CqvP0","title":"The Periodic Table: Atomic Radius, Ionization Energy, and Electronegativity","channel":"Professor Dave Explains","minutes":8},{"url":"https://www.youtube.com/watch?v=4Url0pjbcuU","title":"Atomic Radius - Basic Introduction - Periodic Table Trends","channel":"The Organic Chemistry Tutor","minutes":14}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('qm-10-other-trends', 'chem-g11-u1-quantum', 10, 'The other trends listed in your objectives', '1.8.3 (objectives)', 'Electron affinity, electronegativity and nonmetallic character follow ionization energy: up across a period, down a group.', '[{"kind":"callout","tone":"book","text":"Your slides end at the ionization energy heading, but the section objectives also list these. Read this in case they appear on the exam; confirm with your teacher what is included."},{"kind":"bullets","items":["**Electron affinity** — the energy change when an atom *gains* an electron.","**Electronegativity** — how strongly an atom pulls shared electrons in a bond.","**Metallic character** — how easily an atom *loses* electrons."]},{"kind":"table","head":["Property","Across →","Down ↓"],"rows":[["Electron affinity","More favorable (generally)","Less favorable (generally)"],["Electro­negativity","Increases","Decreases"],["Metallic character","Decreases","Increases"]]},{"kind":"p","text":"Same two reasons as before: across a period, higher Z_eff means a stronger grip on electrons (less metallic, more electronegative); down a group, electrons are farther away and easier to lose (more metallic). Fluorine is the most electronegative element; the most metallic are at the bottom left (Cs, Fr)."}]'::jsonb, '[{"q":"Where in the periodic table are the most metallic elements, and why?","a":"Bottom left. Their outer electrons are far from the nucleus and weakly held, so they are lost easily."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.subjects (id, name, grade, sort_order) values ('chemistry', 'Chemistry', 'Grade 11', 1) on conflict (id) do update set name = excluded.name, grade = excluded.grade, sort_order = excluded.sort_order;
insert into public.subject_chapters (id, subject_id, unit, title, source, intro, exam_date, sort_order) values ('chem-g11-u2-ionic', 'chemistry', 'Unit 2 · Part A', 'Why atoms bond, and ionic bonding', 'Textbook sections 2.1–2.2 (pages 67–82)', 'Everything in this unit answers one question: **what holds particles together, and how does that decide a substance’s properties?** Atoms bond because the bonded arrangement has **lower energy** than the separate atoms. Part A covers the first way to do it — one atom *gives* electrons to another, and the opposite charges stick. Watch for the surprise in section 3: making the ions actually *costs* energy, and the payoff comes afterwards.', null, 3) on conflict (id) do update set subject_id = excluded.subject_id, unit = excluded.unit, title = excluded.title, source = excluded.source, intro = excluded.intro, exam_date = excluded.exam_date, sort_order = excluded.sort_order;
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2a-1-why-bond', 'chem-g11-u2-ionic', 1, 'Why atoms bond at all', '2.1 · p. 67–68', 'Atoms bond to reach a lower-energy, more stable arrangement — usually 8 outer electrons, like a noble gas.', '[{"kind":"p","text":"A **chemical bond** is the attractive force that holds atoms, ions or molecules together. Atoms don’t bond to be ‘happy’ — they bond because the bonded state has **lower energy** than the separate atoms, and nature always slides toward lower energy."},{"kind":"callout","tone":"idea","title":"The octet rule","text":"Noble gases (ns² np⁶) barely react: their 8 outer electrons are a very stable arrangement. Other atoms tend to **gain, lose or share electrons until they also have 8 in their outer shell**. (Hydrogen, lithium, beryllium and boron aim for 2, like helium.)"},{"kind":"table","head":["Atoms involved","What happens","Bond"],"rows":[["Metal + non-metal","Electrons are **transferred**","Ionic"],["Non-metal + non-metal","Electrons are **shared**","Covalent"],["Metal + metal","Electrons are **pooled** in a ‘sea’","Metallic"]]},{"kind":"p","text":"Why this pattern? Metals (left of the table) hold their outer electrons loosely and lose them easily; non-metals (right) pull electrons strongly. Opposites transfer; two strong pullers can only share; two weak holders pool."}]'::jsonb, '[{"q":"What type of bond forms between magnesium and oxygen? Between nitrogen and fluorine?","a":"Mg + O: metal + non-metal → ionic. N + F: two non-metals → covalent."},{"q":"Why are noble gases unreactive?","a":"They already have a full outer shell (ns² np⁶), a very stable, low-energy arrangement — high ionization energy and no tendency to gain electrons."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=S_k0kr2eZSQ","title":"Introduction to Ionic Bonding and Covalent Bonding","channel":"The Organic Chemistry Tutor","minutes":13}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2a-2-ionic-lewis', 'chem-g11-u2-ionic', 2, 'How an ionic bond forms — and Lewis symbols', '2.2 · p. 69–71', 'The metal gives its outer electrons to the non-metal; the resulting + and − ions attract each other.', '[{"kind":"example","title":"Sodium chloride, step by step","steps":["Na ([Ne] 3s¹) loses its one outer electron → Na⁺ ([Ne]).","Cl ([Ne] 3s² 3p⁵) gains that electron → Cl⁻ ([Ar]).","Na⁺ and Cl⁻ attract each other electrostatically → NaCl."],"answer":"Both ions end with a noble-gas configuration; the bond is the attraction between them."},{"kind":"p","text":"A **Lewis symbol** is the element symbol with one dot for each **valence electron**: Na has 1 dot, Cl has 7. To show ionic bonding, move the dots: Na loses its dot and becomes [Na]⁺; Cl gets an eighth dot and becomes [Cl]⁻ in brackets."},{"kind":"callout","tone":"idea","title":"Working out the formula","text":"The charges must cancel. Ca gives away **2** electrons but each Cl takes only **1**, so you need two Cl: **CaCl₂**. Al gives 3 and O takes 2 → the smallest numbers that balance are 2 Al (+6) and 3 O (−6): **Al₂O₃**."},{"kind":"p","text":"Ions don’t form isolated pairs. Each ion attracts as many opposite ions as possible, so millions of them stack into a regular **crystal lattice** — which is why ionic compounds are solids."}]'::jsonb, '[{"q":"Use the electron-transfer idea to give the formula of the compound of lithium and oxygen.","a":"Li gives 1 electron, O needs 2, so two Li are needed: Li₂O."},{"q":"Why does Na⁺ not react the way a sodium atom does?","a":"Na⁺ has already lost its outer electron and has the stable [Ne] configuration; the reactive 3s electron is gone."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=Qf07-8Jhhpc","title":"Ionic Bonding Introduction","channel":"Tyler DeWitt","minutes":7}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2a-3-lattice-energy', 'chem-g11-u2-ionic', 3, 'The energy puzzle: lattice energy and the Born–Haber cycle', '2.2 · p. 72–73', 'Making ions costs energy; the huge energy released when the ions pack into a crystal pays for it.', '[{"kind":"p","text":"Surprise: transferring the electron **absorbs** energy. For LiF, removing Li’s electron costs +520 kJ and F gaining it releases only 328 kJ, so the transfer alone costs **+192 kJ**. Yet LiF forms readily. Why?"},{"kind":"callout","tone":"idea","text":"Because when the gaseous ions come together into a solid, a **huge** amount of energy is released (about 1050 kJ for LiF). That release — the **lattice energy** — is far bigger than the cost of making the ions. **Ionic solids exist only because the lattice energy beats the cost of electron transfer.**"},{"kind":"p","text":"**Lattice energy (U):** the energy needed to separate 1 mol of an ionic solid into gaseous ions. It can’t be measured directly, so we calculate it with **Hess’s law**: the total energy change is the same whichever route you take."},{"kind":"example","title":"Born–Haber cycle for NaCl (the book’s example)","steps":["Route 1 (direct): Na(s) + ½Cl₂(g) → NaCl(s), ΔH_f = −411 kJ.","Route 2, step by step: vaporize Na +108 · break ½Cl₂ +120 · ionize Na +496 · Cl gains e⁻ −349 · ions form the solid = ?","Both routes must total −411: −411 = 108 + 120 + 496 − 349 + (ions → solid).","Ions → solid = −411 − 375 = −786 kJ."],"answer":"Forming the solid from ions releases 786 kJ, so the lattice energy of NaCl is 786 kJ/mol."},{"kind":"callout","tone":"book","title":"About the sign in your book","text":"The book defines lattice energy as the energy to **separate** the solid (a positive number), but its worked answer is written as **−786**. That −786 is the energy of **forming** the solid from ions. Same size, opposite direction. If an exam asks for the lattice energy, 786 kJ/mol is the magnitude; follow your teacher’s sign convention."}]'::jsonb, '[{"q":"If electron transfer absorbs energy, why do ionic compounds form?","a":"The lattice energy released when the ions pack into a solid is much larger than the energy needed to make the ions, so the overall process releases energy."},{"q":"What law lets us calculate lattice energy indirectly?","a":"Hess’s law: the enthalpy change is the same by any route, so the unknown step equals the direct ΔH_f minus the sum of the other steps."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=DI-bwx8r3r8","title":"Born Haber Cycle, Basic Introduction, Lattice Energy, Hess Law","channel":"The Organic Chemistry Tutor","minutes":10}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2a-4-lattice-factors', 'chem-g11-u2-ionic', 4, 'What makes an ionic bond strong', '2.2 · p. 74–75', 'U ∝ (q₁ × q₂) / r — bigger charges and smaller ions give a stronger ionic bond.', '[{"kind":"formula","text":"U ∝ (q₁ × q₂) / r","note":"q = charges on the ions, r = distance between their centres"},{"kind":"bullets","items":["**Charge matters most.** Mg²⁺O²⁻ (2 × 2 = 4) has a far larger lattice energy than Na⁺F⁻ (1 × 1 = 1).","**Then size.** Smaller ions sit closer together (smaller r), so they attract more strongly.","Ionic bonds also form more easily when the metal has a **low ionization energy** and the non-metal a **high electron affinity**."]},{"kind":"example","title":"Exercise 2.3 Q6 — which has the LOWER lattice energy?","steps":["CaS or BaS → **BaS**: Ba²⁺ is bigger than Ca²⁺ (same charges).","NaF or MgO → **NaF**: charges 1 × 1 versus 2 × 2.","LiCl or CsCl → **CsCl**: Cs⁺ is much bigger than Li⁺.","BaS or CsCl → **CsCl**: charges 1 × 1 versus 2 × 2."],"answer":"Check charges first; if they are equal, the larger ions give the lower lattice energy."},{"kind":"p","text":"Activity 2.7: **MgO** has stronger ionic bonding than LiF (similar sizes, double charges). **NaCl** is stronger than KCl (Na⁺ is smaller than K⁺: 102 vs 138 pm)."}]'::jsonb, '[{"q":"Which has the higher melting point, NaCl or MgO? Why?","a":"MgO. Its ions carry 2+ and 2− charges, so the lattice energy (and the attraction to overcome on melting) is much larger."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=I61-N0GuSx8","title":"Lattice Energy of Ionic Compounds — Charge vs Ion Size","channel":"The Organic Chemistry Tutor","minutes":14}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2a-5-ion-exceptions', 'chem-g11-u2-ionic', 5, 'Ions that don’t end with an octet', '2.2 · p. 76–78', 'Small atoms copy helium (2 electrons); transition-metal ions often have no noble-gas arrangement at all.', '[{"kind":"bullets","items":["**Fewer than 8 (a ‘duet’):** H⁻, Li⁺, Be²⁺ and B³⁺ end with 2 electrons, like helium.","**Transition metals lose their 4s electrons first**, even though 4s filled before 3d. Fe = [Ar] 4s² 3d⁶ → Fe²⁺ = [Ar] 3d⁶ → Fe³⁺ = [Ar] 3d⁵. Neither iron ion looks like a noble gas, yet both are stable.","**Zn²⁺ = [Ar] 3d¹⁰ and Ga³⁺ = [Ar] 3d¹⁰:** a full outer set ns² np⁶ nd¹⁰ (18 electrons) — sometimes called a ‘pseudo-noble-gas’ configuration."]},{"kind":"callout","tone":"warn","title":"The rule that catches people","text":"When an atom becomes a positive ion, it loses electrons from the **highest n first** — 4s before 3d, and for gallium 4p then 4s. Write the atom’s configuration, then remove from the outermost shell."},{"kind":"p","text":"Why does Fe³⁺ form so readily? 3d⁵ is half-filled — the same extra stability you met with chromium in Unit 1."}]'::jsonb, '[{"q":"Write the configurations of Sn, Sn²⁺ and Sn⁴⁺ (Sn = [Kr] 5s² 4d¹⁰ 5p²).","a":"Sn²⁺ = [Kr] 5s² 4d¹⁰ (loses 5p first); Sn⁴⁺ = [Kr] 4d¹⁰ (then 5s). Neither is isoelectronic with a noble gas."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2a-6-ionic-properties', 'chem-g11-u2-ionic', 6, 'Properties of ionic compounds — and why', '2.2 · p. 78–82 (experiments)', 'Every ionic property comes from strong attractions between fixed, charged ions in a lattice.', '[{"kind":"table","head":["Property","Reason"],"rows":[["High melting points","Strong attractions between ions in every direction must be overcome"],["Hard but brittle","A blow shifts a layer; like charges line up, repel, and the crystal cracks"],["Don’t conduct as solids","Ions are locked in place — nothing can move"],["Conduct when molten or dissolved","Ions are free to move and carry charge"],["Often soluble in water, not in non-polar solvents","Polar water molecules surround and pull ions out of the lattice"]]},{"kind":"callout","tone":"idea","text":"This is exactly what the book’s experiments (PbI₂, NaCl, CuCl₂) are designed to show: the solid doesn’t conduct, the melt and the solution do."}]'::jsonb, '[{"q":"Why does solid NaCl not conduct electricity, but molten NaCl does?","a":"Conduction needs moving charges. In the solid, the ions are fixed in the lattice; when molten, they can move."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=zpaHPXVR8WU","title":"What are Ionic Bonds? Properties of Matter","channel":"FuseSchool","minutes":3}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.subject_chapters (id, subject_id, unit, title, source, intro, exam_date, sort_order) values ('chem-g11-u2-covalent', 'chemistry', 'Unit 2 · Part B', 'Covalent bonds, molecular shapes and intermolecular forces', 'Textbook section 2.3 (pages 83–110)', 'Two non-metals both want electrons, so neither gives — they **share**. Part B follows one chain of reasoning: draw the **Lewis structure** → count electron groups to get the **shape** (VSEPR) → combine shape and bond polarity to see whether the molecule is **polar** → polarity decides the **forces between molecules** → those forces decide boiling point, melting point and solubility. Learn the chain and you can answer questions you have never seen.', null, 4) on conflict (id) do update set subject_id = excluded.subject_id, unit = excluded.unit, title = excluded.title, source = excluded.source, intro = excluded.intro, exam_date = excluded.exam_date, sort_order = excluded.sort_order;
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2b-1-covalent-bond', 'chem-g11-u2-covalent', 1, 'What a covalent bond is', '2.3 · p. 83–85', 'A shared pair of electrons is attracted to both nuclei at once — that shared attraction is the bond.', '[{"kind":"p","text":"As two H atoms approach, each nucleus attracts **both** electrons. Nuclei repel each other and electrons repel each other, but at the right distance the attractions win. The energy is lowest at **74 pm** — the H–H **bond length**."},{"kind":"bullets","items":["Too far apart: little attraction, no bond.","Too close: the nuclei repel strongly, energy shoots up.","At the bond length: maximum net attraction, lowest energy, most stable."]},{"kind":"table","head":["Bond","Shared pairs","Example"],"rows":[["Single","1","H–H, F–F"],["Double","2","O=O"],["Triple","3","N≡N"]]},{"kind":"p","text":"Shared pairs are **bonding pairs**; pairs that stay on one atom are **lone pairs** (non-bonding pairs). More shared pairs → shorter, stronger bond."}]'::jsonb, '[{"q":"Why doesn’t hydrogen form an ionic bond by losing its electron?","a":"Its ionization energy is high and H⁺ would be a bare proton; sharing gives it the stable 1s² arrangement without that cost."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2b-2-lewis', 'chem-g11-u2-covalent', 2, 'Drawing Lewis structures in four steps', '2.3 · p. 86–89', 'Count all valence electrons, connect the atoms, complete the outer atoms, then fix the centre with multiple bonds.', '[{"kind":"steps","items":["**Count valence electrons** for all atoms. Add one per negative charge; subtract one per positive charge.","**Skeleton:** the least electronegative atom goes in the centre (never H — it is always on the outside). Connect with single bonds.","**Complete octets on the outer atoms** with lone pairs. Put any leftover electrons on the central atom.","**Central atom short of 8?** Move a lone pair from an outer atom into a double (or triple) bond."]},{"kind":"example","title":"NF₃ (book example 2.2)","steps":["Electrons: 5 + 3 × 7 = 26.","N in the centre, three N–F bonds (6 electrons used).","Each F gets 3 lone pairs (18 more → 24). The last 2 go on N as a lone pair."],"answer":"N has 3 bonds + 1 lone pair; every atom has an octet."},{"kind":"example","title":"Carbonate ion, CO₃²⁻ (book example 2.3)","steps":["Electrons: 4 + 3 × 6 + 2 = 24.","C in the centre with three C–O bonds; complete each O → all 24 used.","C has only 6 electrons, so move one O lone pair into a C=O double bond."],"answer":"One C=O and two C–O, with brackets and a 2− charge on the whole ion."},{"kind":"callout","tone":"warn","text":"Always **check your total** at the end: the electrons drawn must equal the number you counted in step 1. Most wrong Lewis structures have the wrong number of electrons."}]'::jsonb, '[{"q":"How many valence electrons are in the NH₄⁺ ion?","a":"5 + 4 × 1 − 1 = 8."},{"q":"Draw (describe) the Lewis structure of CO₂.","a":"16 electrons: O=C=O with two lone pairs on each O; carbon has two double bonds and no lone pairs."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=1ZlnzyHahvo","title":"How to Draw Lewis Structures: Five Easy Steps","channel":"Wayne Breslyn","minutes":6}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2b-3-coordinate-resonance', 'chem-g11-u2-covalent', 3, 'Coordinate bonds and resonance', '2.3 · p. 90–92', 'A coordinate bond has both shared electrons from one atom; resonance means the real molecule is a blend of several drawings.', '[{"kind":"heading","text":"Coordinate (dative) covalent bonds"},{"kind":"p","text":"Usually each atom gives one electron to a bond. In a **coordinate bond**, one atom gives **both** — a lone pair — to an atom with an empty orbital. NH₃ + H⁺ → NH₄⁺: nitrogen’s lone pair bonds to the bare H⁺. Once formed, it is identical to the other N–H bonds."},{"kind":"p","text":"Examples: NH₄⁺, H₃O⁺ (water’s lone pair + H⁺), AlCl₄⁻ (Cl⁻ donates to AlCl₃), and the addition compound H₃N→BCl₃ (NH₃’s lone pair fills boron’s empty orbital)."},{"kind":"callout","tone":"book","title":"Correction to the book’s list","text":"The book lists **NH₃** and **BCl₃** as containing coordinate bonds. On their own they don’t: NH₃ is the *donor* and BCl₃ the *acceptor*. The coordinate bond only appears when they **combine**: H₃N→BCl₃."},{"kind":"heading","text":"Resonance"},{"kind":"p","text":"Ozone (O₃) can be drawn with the double bond on the left **or** on the right. But measurements show both O–O bonds are **identical** (1.278 Å), halfway between single and double. Neither drawing is the real molecule: the real one is a **resonance hybrid**, an average of both. The electrons are **delocalized** — spread over both bonds."},{"kind":"callout","tone":"warn","text":"The ↔ arrow does **not** mean the molecule flips back and forth. There is one ozone molecule, all the time, with two 1½ bonds. Same for NO₂⁻ and CO₃²⁻."}]'::jsonb, '[{"q":"How is a coordinate bond different from an ordinary covalent bond once formed?","a":"It isn’t — only its origin differs (both electrons came from one atom). In NH₄⁺ all four N–H bonds are identical."},{"q":"Why do we need resonance structures for O₃?","a":"Both O–O bonds are identical in length, but no single Lewis structure shows that; the real molecule is the average of the two drawings."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=9B5FGPDwX_E","title":"Resonance Structures, Basic Introduction","channel":"The Organic Chemistry Tutor","minutes":11}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2b-4-octet-exceptions', 'chem-g11-u2-covalent', 4, 'Covalent molecules that break the octet rule', '2.3 · p. 93–94', 'Some central atoms have fewer than 8, some have more than 8, and some molecules have an odd number of electrons.', '[{"kind":"table","head":["Type","Examples","Why"],"rows":[["Fewer than 8","BeCl₂ (4), BF₃ (6), AlCl₃ (6)","Be, B, Al have only 2–3 valence electrons to share"],["More than 8 (expanded)","PCl₅ (10), SF₆ (12), XeF₄ (12)","Period 3 and below: bigger atoms with empty d orbitals"],["Odd number","NO (11), NO₂ (17), ClO₂ (19)","One electron must be unpaired (a free radical)"]]},{"kind":"callout","tone":"idea","text":"**Why can’t nitrogen make NCl₅ when phosphorus makes PCl₅?** Nitrogen is in period 2: it has no d orbitals and is too small to fit five atoms around it. Only period-3-and-below atoms can expand their octet."},{"kind":"p","text":"Electron-deficient molecules like BF₃ grab a lone pair when they can: BF₃ + F⁻ → BF₄⁻ (a coordinate bond completes boron’s octet)."}]'::jsonb, '[{"q":"In PCl₃, PCl₅, OF₂, BF₃ and SiF₄, which central atoms do NOT obey the octet rule?","a":"P in PCl₅ (10 electrons) and B in BF₃ (6). The others have exactly 8."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=96L6_IwyHRM","title":"Exceptions To The Octet Rule","channel":"The Organic Chemistry Tutor","minutes":13}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2b-5-vsepr', 'chem-g11-u2-covalent', 5, 'VSEPR: predicting the shape of a molecule', '2.3 · p. 99–103', 'Electron groups around the central atom push as far apart as possible; lone pairs push hardest.', '[{"kind":"steps","items":["Draw the Lewis structure.","Count **electron groups** on the central atom: each bond (single, double or triple counts as **one**) plus each lone pair.","The number of groups gives the **arrangement**; the number of **atoms** gives the **shape**.","Lone pairs squeeze bond angles: **lone–lone > lone–bond > bond–bond** repulsion."]},{"kind":"table","head":["Groups","Lone pairs","Shape (example)","Angle"],"rows":[["2","0","Linear (BeCl₂, CO₂)","180°"],["3","0","Trigonal planar (BF₃)","120°"],["3","1","Bent (SO₂)","< 120°"],["4","0","Tetrahedral (CH₄)","109.5°"],["4","1","Trigonal pyramidal (NH₃)","107°"],["4","2","Bent (H₂O)","104.5°"],["5","0","Trigonal bipyramidal (PCl₅)","90°, 120°"],["5","1","Seesaw (SF₄)","—"],["6","0","Octahedral (SF₆)","90°"],["6","1","Square pyramidal (IF₅)","≈ 90°"],["6","2","Square planar (XeF₄)","90°"]]},{"kind":"callout","tone":"idea","title":"Why the angles shrink","text":"CH₄, NH₃ and H₂O all have 4 electron groups — a tetrahedral **arrangement**. But each lone pair takes up more room than a bond, so the angle drops: **109.5° → 107° → 104.5°** as lone pairs go 0 → 1 → 2."},{"kind":"p","text":"Why is SF₄’s lone pair in the middle ring (equatorial), not at the top? There it has only two neighbours at 90° instead of three — less repulsion."}]'::jsonb, '[{"q":"Predict the shape of PF₃.","a":"P has 3 bonds + 1 lone pair = 4 groups → trigonal pyramidal (like NH₃)."},{"q":"CO₂ has two double bonds. How many electron groups does carbon have, and what is the shape?","a":"Two (each double bond counts as one group), so it is linear, 180°."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=Q9-JjyAEqnU","title":"VSEPR Theory and Molecular Geometry","channel":"Professor Dave Explains","minutes":7}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2b-6-polarity', 'chem-g11-u2-covalent', 6, 'Polar bonds and polar molecules', '2.3 · p. 103–106', 'A molecule is polar only if its bond dipoles don’t cancel — and whether they cancel depends on its shape.', '[{"kind":"p","text":"In a bond between different atoms, the more **electronegative** atom pulls the shared electrons closer and gets a partial negative charge (δ−); the other gets δ+. That is a **polar bond**. Identical atoms (H₂, Cl₂) share equally — **non-polar**."},{"kind":"p","text":"A **dipole moment** (μ, in debye D) measures how unevenly charge is spread across the whole molecule. μ = 0 means non-polar."},{"kind":"table","head":["Molecule","Bonds","Shape","Result"],"rows":[["CO₂","Polar C=O","Linear — pulls opposite","Cancel → non-polar (μ = 0)"],["H₂O","Polar O–H","Bent — pulls don’t oppose","Polar (μ = 1.87 D)"],["CCl₄","Polar C–Cl","Tetrahedral, all the same","Cancel → non-polar"],["CHCl₃","One C–H swapped in","Tetrahedral, unbalanced","Polar"]]},{"kind":"callout","tone":"idea","title":"Think of it as a tug-of-war","text":"Each polar bond is a rope pulling toward its negative end. If identical ropes pull in perfectly opposite or symmetric directions, nothing moves (non-polar). If the shape is lopsided, there is a net pull (polar)."},{"kind":"p","text":"cis-1,2-dichloroethene (both Cl on the same side) is polar, μ = 1.89 D; trans (opposite sides) is non-polar, μ = 0 — same atoms, different arrangement."},{"kind":"callout","tone":"book","text":"The book calls cis- and trans-dichloroethene ‘constitutional isomers’. They are **geometric (cis–trans) isomers**: same atoms bonded in the same order, arranged differently in space."}]'::jsonb, '[{"q":"Is NH₃ polar? Explain.","a":"Yes. The N–H bonds are polar and the pyramidal shape (with a lone pair on top) means their pulls don’t cancel."},{"q":"Water’s dipole moment is 1.87 D. Why does this prove water is bent?","a":"If it were linear like CO₂, the two O–H dipoles would cancel to zero. A non-zero dipole means they don’t cancel, so the molecule must be bent."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=ds5HXmBkO0Y","title":"Bond Polarity, Electronegativity and Dipole Moment","channel":"The Organic Chemistry Tutor","minutes":11}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2b-7-imf', 'chem-g11-u2-covalent', 7, 'Forces between molecules', '2.3 · p. 107–110', 'Intermolecular forces are weak attractions BETWEEN molecules; they decide boiling and melting points.', '[{"kind":"callout","tone":"warn","title":"Don’t mix these up","text":"**Intra**molecular = the covalent bonds **inside** a molecule (strong). **Inter**molecular = attractions **between** molecules (weak). Boiling water separates the molecules (intermolecular); it does **not** break O–H bonds."},{"kind":"table","head":["Force","Between","Strength"],"rows":[["London (dispersion)","All molecules — temporary dipoles","Weakest per contact; grows with size"],["Dipole–dipole","Polar molecules — δ+ attracts δ−","Medium"],["Hydrogen bond","H on N, O or F … lone pair on N, O or F","Strongest of the three"]]},{"kind":"bullets","items":["**London forces** arise because electrons move: for an instant one side of a molecule has more electrons, making a temporary dipole that induces one in the neighbour. Bigger molecules (more electrons) → stronger London forces → higher boiling point.","**Shape matters too:** n-pentane (long chain, more contact) boils at 36 °C; its compact isomer 2,2-dimethylpropane at 9.5 °C.","**Hydrogen bonds** need H attached **directly** to N, O or F. That H is almost a bare proton, so it is strongly attracted to a lone pair on a neighbouring N, O or F.","‘Van der Waals forces’ is the umbrella term for dipole–dipole and London forces."]},{"kind":"example","title":"Why is H₂O a liquid but CH₄ a gas at room temperature?","steps":["Both are small molecules of similar mass.","CH₄ is non-polar: only weak London forces.","H₂O is polar and has hydrogen bonds (O–H … O)."],"answer":"Hydrogen bonds hold water molecules together far more strongly, so water needs much more energy to boil."},{"kind":"p","text":"Ice floats because hydrogen bonds lock the molecules into an open hexagonal pattern that takes up **more** space than liquid water. One water molecule can form up to **4** hydrogen bonds (2 through its H atoms, 2 through its lone pairs)."}]'::jsonb, '[{"q":"Which has the higher boiling point, cis- or trans-1,2-dichloroethene? Why?","a":"cis. It is polar, so it has dipole–dipole forces in addition to London forces; trans is non-polar."},{"q":"Can CH₄ form hydrogen bonds? Why or why not?","a":"No. Its hydrogens are bonded to carbon, not to N, O or F."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=XSRa9P-xJl0","title":"Intermolecular Forces — Hydrogen Bonding, Dipole Dipole, London","channel":"The Organic Chemistry Tutor","minutes":11}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2b-8-covalent-properties', 'chem-g11-u2-covalent', 8, 'Properties of covalent (molecular) substances', '2.3 · p. 96–99', 'Strong bonds inside the molecules, weak forces between them — so they melt and boil easily.', '[{"kind":"table","head":["Property","Reason"],"rows":[["Low melting and boiling points; often gases or liquids","Only weak intermolecular forces hold the molecules together"],["Don’t conduct, even when melted","Neutral molecules — no ions or free electrons"],["Usually dissolve in non-polar solvents","‘Like dissolves like’: similar intermolecular forces mix"],["Polar ones (ethanol, sugar, NH₃) can dissolve in water","They hydrogen-bond or dipole-bond with water"]]},{"kind":"p","text":"That last row is why NH₃ dissolves in water while CH₄ doesn’t: NH₃ hydrogen-bonds with water; CH₄ can’t."}]'::jsonb, '[{"q":"Why doesn’t molten sugar or liquid methane conduct electricity, when molten salt does?","a":"They are made of neutral molecules; there are no ions or free electrons to carry charge."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.subject_chapters (id, subject_id, unit, title, source, intro, exam_date, sort_order) values ('chem-g11-u2-theories', 'chemistry', 'Unit 2 · Part C', 'Metallic bonding, bonding theories and crystals', 'Textbook sections 2.4–2.6 and the review exercise (pages 111–143)', 'Lewis dots and VSEPR tell you *what* shape a molecule has, but not *why* bonds form where they do. Part C gives two deeper pictures: **valence bond theory** (orbitals overlap; hybrid orbitals explain the angles) and **molecular orbital theory** (electrons spread over the whole molecule — the only model that explains why O₂ is magnetic). It opens with metallic bonding and finishes by sorting every solid into four crystal types.', null, 5) on conflict (id) do update set subject_id = excluded.subject_id, unit = excluded.unit, title = excluded.title, source = excluded.source, intro = excluded.intro, exam_date = excluded.exam_date, sort_order = excluded.sort_order;
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2c-1-metallic', 'chem-g11-u2-theories', 1, 'Metallic bonding: the electron sea', '2.4 · p. 111–113', 'Metal ions sit in a ‘sea’ of shared, free-moving valence electrons — and that sea explains every metal property.', '[{"kind":"p","text":"Each metal atom releases its valence electrons into a pool shared by the whole piece. What’s left is a regular array of **positive metal ions** in a **sea of delocalized electrons**. The bond is the attraction between the ions and the sea."},{"kind":"table","head":["Property","Why"],"rows":[["Conduct electricity and heat, even solid","The electrons move freely through the metal"],["Malleable and ductile","Layers of ions can slide; the electron sea moves with them, so nothing breaks"],["Shiny","Free electrons reflect light"],["High boiling points","Each ion must be torn away from the electron sea"]]},{"kind":"callout","tone":"idea","title":"Metal vs ionic solid under a hammer","text":"Hit an ionic crystal and like charges line up and repel: it **shatters**. Hit a metal and the layers slide while the electron sea keeps holding them: it **bends**."},{"kind":"example","title":"The book’s activity — explain the numbers","steps":["Li melts at 180 °C but boils at 1317 °C: melting only loosens the array; boiling must pull each ion out of the electron sea.","Be melts at 1287 °C, Li at 180 °C: Be gives 2 electrons to the sea and forms a smaller 2+ ion — much stronger attraction.","Na melts at 98 °C, K at 63 °C: K⁺ is bigger, so the sea is farther from its centre and attraction is weaker."],"answer":"More delocalized electrons, higher ion charge and smaller ions → stronger metallic bonding."},{"kind":"callout","tone":"book","text":"The book gives sodium’s melting point as 89 °C in one place; the accepted value is about **98 °C**. The comparison with potassium (63 °C) works either way."}]'::jsonb, '[{"q":"Why are Group 2 metals harder and higher-melting than Group 1 metals?","a":"They contribute two electrons each to the electron sea and form 2+ ions, so the attraction between ions and electrons is stronger."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=S08qdOTd0w0","title":"What Are Metallic Bonds? Properties of Matter","channel":"FuseSchool","minutes":4}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2c-2-vb-sigma-pi', 'chem-g11-u2-theories', 2, 'Valence bond theory: overlap, σ and π bonds', '2.5 · p. 114–118', 'A covalent bond forms where two half-filled orbitals overlap; head-on overlap gives σ, side-by-side gives π.', '[{"kind":"p","text":"Valence bond theory says: a bond forms when an orbital from each atom **overlaps**, and the overlap region holds a pair of electrons with opposite spins. More overlap → stronger bond."},{"kind":"table","head":["","Sigma (σ)","Pi (π)"],"rows":[["Overlap","Head-on, along the line between nuclei","Side-by-side, above and below that line"],["Formed from","s–s, s–p, p–p (end-on), hybrids","Only parallel p orbitals"],["Strength","Stronger (more overlap)","Weaker"],["Rotation","Free","Prevents rotation"]]},{"kind":"callout","tone":"idea","title":"Counting σ and π","text":"**Single = 1σ · Double = 1σ + 1π · Triple = 1σ + 2π.** Every bond starts with exactly one σ; extra pairs are π. Bonds involving an s orbital are always σ."}]'::jsonb, '[{"q":"True or false: a double bond consists of two σ bonds.","a":"False. A double bond is one σ and one π."},{"q":"How many σ and π bonds are in N₂?","a":"N≡N: one σ and two π."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=pT8nrBrTOm4","title":"Sigma and Pi Bonds Explained","channel":"The Organic Chemistry Tutor","minutes":6}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2c-3-hybridization', 'chem-g11-u2-theories', 3, 'Hybridization: sp, sp² and sp³', '2.5 · p. 119–123', 'An atom mixes its s and p orbitals into identical hybrid orbitals that point toward the corners of the VSEPR shape.', '[{"kind":"p","text":"**The puzzle:** ground-state carbon (2s² 2p²) has only 2 unpaired electrons, so it ‘should’ form CH₂. But it forms **CH₄**, with four identical bonds at 109.5°. Hybridization explains it: one 2s electron is promoted to 2p (4 unpaired), then the 2s and three 2p orbitals **mix** into four identical **sp³** orbitals."},{"kind":"table","head":["Hybrid","Mixes","Geometry, angle","Example"],"rows":[["sp","1 s + 1 p","Linear, 180°","BeCl₂"],["sp²","1 s + 2 p","Trigonal planar, 120°","BCl₃"],["sp³","1 s + 3 p","Tetrahedral, 109.5°","CH₄"]]},{"kind":"callout","tone":"idea","title":"Shortcut","text":"**Number of hybrid orbitals = number of electron groups on the atom.** 2 groups → sp, 3 → sp², 4 → sp³. Count groups exactly as in VSEPR."},{"kind":"p","text":"**NH₃ and H₂O are sp³ too** — they have 4 electron groups. One (NH₃) or two (H₂O) hybrid orbitals hold lone pairs, which squeeze the angle to 107° and 104.5°."},{"kind":"p","text":"s-character: sp = 50%, sp² = 33%, sp³ = 25% (one s out of 2, 3 or 4 orbitals mixed)."}]'::jsonb, '[{"q":"What is the hybridization of N in NH₃?","a":"sp³: 3 bonds + 1 lone pair = 4 electron groups."},{"q":"Why is the H–O–H angle smaller than the H–N–H angle?","a":"Both atoms are sp³, but O has two lone pairs and N only one. More lone-pair repulsion squeezes the bonds closer together."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=pdJeQUd2g_4","title":"Hybridization of Atomic Orbitals — Sigma & Pi Bonds — sp sp2 sp3","channel":"The Organic Chemistry Tutor","minutes":11}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2c-4-d-hybrids', 'chem-g11-u2-theories', 4, 'Hybrids with d orbitals: sp³d and sp³d²', '2.5 · p. 123–127', 'Period-3-and-below atoms can mix in d orbitals to make 5 or 6 hybrids — matching 5 or 6 electron groups.', '[{"kind":"table","head":["Groups","Hybrid","Arrangement","Example"],"rows":[["5","sp³d","Trigonal bipyramidal","PCl₅"],["6","sp³d²","Octahedral","SF₆, IF₅"]]},{"kind":"bullets","items":["**PCl₅:** 3 equatorial bonds at 120° and 2 axial at 90° to that plane. The axial bonds feel more repulsion, so they are slightly longer and weaker.","**SF₆:** six identical S–F bonds pointing to the corners of an octahedron.","**IF₅:** six groups (5 bonds + 1 lone pair) → sp³d² → square pyramidal."]},{"kind":"steps","items":["Draw a reasonable Lewis structure.","Use VSEPR to get the electron-group arrangement.","Pick the hybrid with the same number of orbitals as groups.","Describe what each hybrid overlaps with."]}]'::jsonb, '[{"q":"Give the hybridization and shape of XeF₄ (4 bonds, 2 lone pairs on Xe).","a":"6 groups → sp³d²; with 2 lone pairs opposite each other the shape is square planar."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2c-5-multiple-bonds', 'chem-g11-u2-theories', 5, 'Hybridization in double and triple bonds', '2.5 · p. 128–130', 'Hybrid orbitals make the σ bonds; the leftover, unhybridized p orbitals make the π bonds.', '[{"kind":"table","head":["Molecule","C hybrid","Shape","Bonds"],"rows":[["Ethane C₂H₆","sp³","Tetrahedral at each C","7 σ"],["Ethene C₂H₄","sp²","Planar, 120°","5 σ + 1 π"],["Ethyne C₂H₂","sp","Linear, 180°","3 σ + 2 π"]]},{"kind":"p","text":"In **ethene**, each carbon uses three sp² hybrids for σ bonds (two to H, one to the other C). Its one leftover p orbital stands perpendicular to the plane; the two leftover p orbitals overlap side-by-side to form the **π bond**. That is why all six atoms lie flat."},{"kind":"callout","tone":"idea","title":"Why there’s no rotation about a double bond","text":"Twisting one carbon would turn its p orbital away from the other one and break the π overlap. A single (σ) bond is symmetric around the axis, so it can spin freely."}]'::jsonb, '[{"q":"How many σ and π bonds are in ethyne, H–C≡C–H?","a":"3 σ (two C–H, one C–C) and 2 π (in the triple bond)."}]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2c-6-mo-theory', 'chem-g11-u2-theories', 6, 'Molecular orbital theory and bond order', '2.5 · p. 131–132', 'Atomic orbitals combine into bonding MOs (lower energy) and antibonding MOs (higher energy); bond order = (bonding − antibonding) ÷ 2.', '[{"kind":"p","text":"MO theory treats the molecule as one unit. **Two atomic orbitals always make two molecular orbitals**: a **bonding** MO (electron density between the nuclei — lower energy, holds atoms together) and an **antibonding** MO, marked ∗ (a node between the nuclei — higher energy, pushes atoms apart)."},{"kind":"formula","text":"Bond order = ½ (electrons in bonding MOs − electrons in antibonding MOs)"},{"kind":"table","head":["Species","Configuration","Bond order","Exists?"],"rows":[["H₂","(σ1s)²","1","Yes"],["H₂⁺","(σ1s)¹","½","Yes"],["He₂⁺","(σ1s)² (σ∗1s)¹","½","Yes (observed)"],["He₂","(σ1s)² (σ∗1s)²","0","No"],["Li₂","(σ1s)² (σ∗1s)² (σ2s)²","1","Yes"]]},{"kind":"callout","tone":"idea","text":"**Bond order > 0 → the molecule can exist; 0 → it falls apart.** Higher bond order → stronger, shorter bond. He₂ doesn’t exist because its antibonding electrons cancel its bonding ones exactly."}]'::jsonb, '[{"q":"Why does He₂ not exist but He₂⁺ does?","a":"He₂ has 2 bonding and 2 antibonding electrons (bond order 0). He₂⁺ has 2 bonding and 1 antibonding (bond order ½), so there is a net bond."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=6tB6E6R_XpQ","title":"Molecular Orbital Theory — Bonding & Antibonding MO — Bond Order","channel":"The Organic Chemistry Tutor","minutes":22}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2c-7-mo-diatomics', 'chem-g11-u2-theories', 7, 'MO diagrams for N₂, O₂ and F₂ — and why O₂ is magnetic', '2.5 · p. 133–134', 'Fill MOs like atomic orbitals (Aufbau, Pauli, Hund); unpaired electrons make a molecule paramagnetic.', '[{"kind":"table","head":["Total electrons","Order of filling"],"rows":[["14 or fewer (up to N₂)","σ1s σ∗1s σ2s σ∗2s **π2p** σ2p π∗2p σ∗2p"],["More than 14 (O₂, F₂)","σ1s σ∗1s σ2s σ∗2s **σ2p** π2p π∗2p σ∗2p"]]},{"kind":"p","text":"The only difference is whether **π2p or σ2p** comes first. The two π2p orbitals have equal energy (degenerate), and so do the two π∗2p orbitals."},{"kind":"table","head":["Molecule","Bond order","Unpaired e⁻","Magnetism"],"rows":[["N₂","3","0","Diamagnetic"],["O₂","2","2 (in π∗)","Paramagnetic"],["F₂","1","0","Diamagnetic"]]},{"kind":"example","title":"O₂, 16 electrons","steps":["Fill: σ1s² σ∗1s² σ2s² σ∗2s² σ2p² π2p⁴ — that uses 14.","The last 2 go into the two π∗2p orbitals — **one each, same spin** (Hund’s rule).","Bonding = 2 + 2 + 2 + 4 = 10; antibonding = 2 + 2 + 2 = 6; bond order = (10 − 6)/2."],"answer":"Bond order 2 (a double bond) with 2 unpaired electrons → paramagnetic."},{"kind":"callout","tone":"idea","title":"Why MO theory wins here","text":"The Lewis structure O=O shows every electron paired, so it predicts O₂ is **not** magnetic. But liquid oxygen sticks to a magnet. Only MO theory, with its two unpaired π∗ electrons, explains this."},{"kind":"p","text":"**Paramagnetic** = has unpaired electrons, attracted to a magnet. **Diamagnetic** = all paired, slightly repelled."}]'::jsonb, '[{"q":"Find the bond order of O₂⁺ and say whether it is stronger than O₂.","a":"Remove one π∗ electron: (10 − 5)/2 = 2.5. Higher than O₂’s 2, so the bond is stronger and shorter."},{"q":"Which would VB/Lewis theory get wrong about O₂?","a":"Its magnetism. The Lewis structure has all electrons paired, but O₂ is paramagnetic because of two unpaired π∗ electrons."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=nTujP4jCbsg","title":"Valence Bond Theory, Hybrid Orbitals, and Molecular Orbital Theory","channel":"Professor Dave Explains","minutes":8}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2c-8-crystals', 'chem-g11-u2-theories', 8, 'Four types of crystalline solid', '2.6 · p. 135–139', 'What the particles are and what holds them together decides how a solid behaves.', '[{"kind":"p","text":"A **crystalline** solid has particles in a regular, repeating 3-D pattern (salt, sugar, metals) and melts at a sharp temperature. An **amorphous** solid (glass, butter) is disordered and softens over a range."},{"kind":"table","head":["Type","Particles and force","Typical properties"],"rows":[["Ionic (NaCl)","Ions, ionic bonds","Hard, brittle, high mp; conducts only melted or dissolved"],["Molecular (ice, I₂, sugar)","Molecules, intermolecular forces","Soft, low mp, non-conductors"],["Covalent network (diamond, SiO₂)","Atoms, covalent bonds throughout","Very hard, very high mp; usually non-conductors"],["Metallic (Cu, Fe)","Metal ions in electron sea","Shiny, malleable, conduct; mp varies"]]},{"kind":"callout","tone":"idea","title":"Diamond vs graphite — same atoms, different networks","text":"Diamond: every C bonded to 4 others in 3-D — the hardest natural substance, no free electrons, doesn’t conduct. Graphite: C bonded to 3 others in flat sheets with one electron per atom delocalized — the sheets slide (soft, slippery) and it **conducts**."},{"kind":"example","title":"The book’s X, Y, Z exercise","steps":["X — brittle, white, mp 800 °C, conducts only if melted/dissolved, soluble → **ionic**.","Y — shiny, malleable, mp 1100 °C, high conductivity → **metallic**.","Z — hard, colorless, mp 3550 °C, doesn’t conduct, insoluble → **covalent network**."],"answer":"Conductivity is the fastest clue: only when molten = ionic; always = metallic; never + very high mp = network."}]'::jsonb, '[{"q":"Why do molecular crystals melt at much lower temperatures than ionic or network solids?","a":"Melting a molecular solid only overcomes weak intermolecular forces; the strong bonds inside the molecules stay intact."}]'::jsonb, '[{"url":"https://www.youtube.com/watch?v=HqV5r9uJ7gY","title":"How to Identify Types of Solid (Ionic, Metallic, Molecular, Network)","channel":"Conquer Chemistry","minutes":5}]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
insert into public.chapter_sections (id, chapter_id, sort_order, title, book_ref, big_idea, body, checks, videos, updated_at) values ('u2c-9-review', 'chem-g11-u2-theories', 9, 'Review exercise — multiple choice, worked', 'Review exercise · p. 141–142', 'Each answer below names the idea it tests, so a wrong answer tells you which section to reread.', '[{"kind":"callout","tone":"warn","title":"Try first","text":"Answer the book’s questions 1–11 on paper before reading these."},{"kind":"table","head":["Q","Answer","Why"],"rows":[["1","c — sharing electrons","Ionic bonds transfer electrons; sharing is covalent"],["2","d — AsF₅","As has 10 electrons around it (expanded octet)"],["3","d — sideways p overlap","That is the definition of a π bond"],["4","d — 4","2 through its H atoms + 2 through its lone pairs"],["5","a — NO₃⁻","3 groups, no lone pair → trigonal planar; the others are pyramidal"],["6","b — acetonitrile + acetone","Both polar, no O–H/N–H to hydrogen-bond"],["7","d — no bond","pₓ and p_y are perpendicular: no net overlap"],["8","a — pentagonal bipyramid","7 bonding groups, no lone pairs"],["9","b — O₃","Commonly drawn with a coordinate O→O bond"],["10","c — SiF₄","Every atom has 8; in the others H has 2 or I has 14"],["11","c — van der Waals","Molecules in a crystal are held by intermolecular forces"]]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, now()) on conflict (id) do update set chapter_id = excluded.chapter_id, sort_order = excluded.sort_order, title = excluded.title, book_ref = excluded.book_ref, big_idea = excluded.big_idea, body = excluded.body, checks = excluded.checks, videos = excluded.videos, updated_at = now();
